# PLOTTING
# ---------------------------------------------------------

# Colors and shifts for plotting
colors = {'EM_Precomp': 'blue', 'Gibbs_Sampling': 'orange', 'Metropolis_Hastings': 'green'}
shifts = {'EM_Precomp': -5, 'Gibbs_Sampling': 0, 'Metropolis_Hastings': 5}

# --- 1. RMSE Plot ---
plt.figure(figsize=(10, 7.5))

agg_rmse = df.groupby('Iteration')[[algo + '_RMSE' for algo in algorithms]].agg(['mean', 'std'])

for algo in algorithms:
    col_name = algo + '_RMSE'
    means = agg_rmse[col_name]['mean']
    stds = agg_rmse[col_name]['std']
    iterations = means.index

    plt.errorbar(iterations + shifts.get(algo, 0), means, label=algo,
                 fmt='-o', color=colors.get(algo, 'black'), capsize=5, elinewidth=1.5)

plt.title('Mean RMSE with Std Error Bars (Filtered)')
plt.xlabel('Iteration')
plt.ylabel('RMSE')
plt.legend()
plt.grid(True, alpha=0.3)
plt.show()

# --- 2. Coverage Plot ---
plt.figure(figsize=(10, 7.5))

agg_cov = df.groupby('Iteration')[[algo + '_Coverage' for algo in algorithms]].agg(['mean', 'std'])

for algo in algorithms:
    col_name = algo + '_Coverage'
    means = agg_cov[col_name]['mean']
    stds = agg_cov[col_name]['std']
    iterations = means.index

    plt.errorbar(iterations + shifts.get(algo, 0), means, label=algo,
                 fmt='-o', color=colors.get(algo, 'black'), capsize=5, elinewidth=1.5)

plt.title('Average Coverage Ratio (%) with Std Error Bars (Filtered)')
plt.xlabel('Iteration')
plt.ylabel('Coverage (%)')
plt.legend()
plt.grid(True, alpha=0.3)
plt.show()

# --- 3. Time Plot (NEW) ---
# Check if Time columns exist.
# Note: In the merge step of the previous script, 'Time' might be suffixed if it existed in both
# (e.g., Time_gibbs, Time_mh) or just 'Time' if only one had it.
# Based on the merge logic: final_results = gb.merge(mh, ..., suffixes=('_gibbs', '_mh'))
