plt.figure(figsize=(10, 7.5))

time_cols = []
if 'Time_gibbs' in df.columns: time_cols.append(('Gibbs_Sampling', 'Time_gibbs'))
if 'Time_mh' in df.columns: time_cols.append(('Metropolis_Hastings', 'Time_mh'))
if 'Time' in df.columns and 'EM_Precomp' in df.columns: time_cols.append(
    ('EM_Precomp', 'Time'))  # Assuming EM time is just 'Time' if generated

if time_cols:
    # Aggregate Time by Iteration
    # We want the mean time taken to reach iteration X across all models

    for algo, t_col in time_cols:
        agg_time = df.groupby('Iteration')[t_col].agg(['mean', 'std'])
        means = agg_time['mean']
        stds = agg_time['std']
        iterations = means.index

        plt.errorbar(iterations, means, yerr=stds, label=algo,
                     fmt='-o', color=colors.get(algo, 'black'), capsize=5, elinewidth=1.5)

    plt.title('Cumulative Learning Time (seconds)')
    plt.xlabel('Iteration')
    plt.ylabel('Time (s)')
    plt.legend()
    plt.grid(True, alpha=0.3)
    plt.show()
else:
    print("No time columns found to plot.")